class NotificationEntity{const NotificationEntity({required this.id,required this.type,required this.title,required this.message,required this.isRead,this.data,this.createdAt});final String id,type,title,message;final bool isRead;final Map<String,dynamic>? data;final DateTime? createdAt;factory NotificationEntity.fromJson(Map<String,dynamic>j)=>NotificationEntity(id:'${j['id']}',type:j['type']??'',title:j['title']??'',message:j['message']??'',isRead:j['read_at']!=null,data:j['data'],createdAt:j['created_at']==null?null:DateTime.tryParse(j['created_at']));}
